Those structs are used to parse incoming binary data from BTP, so lets say we have this:

enum BTP_PACS_CHR __packed {
   BTP_PACS_CHARACTERISTIC_SINK_PAC = 0x01,
   BTP_PACS_CHARACTERISTIC_SOURCE_PAC = 0x02,
}

struct btp_pacs_cmd {
  enum BTP_PACS_CHR chr;
}

and then we use it in handler cb to parse 1 byte buffer, where cmd[0] = 0x42
static uint8_t pacs_cmd(const void *cmd, uint16_t cmd_len,  void *rsp, uint16_t *rsp_len)
{
   const struct btp_pacs_cmd *cp = cmd;

   so now cp->chr has bianry value of 0x42 which is outside of defined enum range
}
